              "<FILL>": "<FILL: remaining fields>"
            }
          ],
          "evVarLabels": {},
          "obVarLabels": {}
        },
        [
          3,
          2
        ]
      ]
    },
    {
      "Box": [
        {
          "newEventVars": {
            "1": [
              "<FILL: event type>"
            ]
          },
          "newObjectVars": {},
          "filters": "<FILL>",
          "sizeFilters": "<FILL>",
          "constraints": [
            {
              "type": "Filter",
              "filter": {
                "type": "TimeBetweenEvents",
                "<FILL>": "<FILL: remaining fields>"
              }
            }
          ],
          "evVarLabels": {},
          "obVarLabels": {}
        },
        []
      ]
    },
    {
      "Box": [
        {
          "newEventVars": {
            "2": [
              "<FILL: event type>"
            ]
          },
          "newObjectVars": {},
          "filters": "<FILL>",
          "sizeFilters": "<FILL>",
          "constraints": [
            {
              "type": "Filter",
              "filter": {
                "type": "TimeBetweenEvents",
                "<FILL>": "<FILL: remaining fields>"
              }
            }
          ],
          "evVarLabels": {},
          "obVarLabels": {}
        },
        []
      ]
    }
  ],
  "edgeNames": [
    [
      [
        0,
